import os,re,collections
def mod2path(m): return m.replace('.','/')+'.lean'
def path2mod(p): return p[:-5].replace('/','.')
allm=set()
for r,d,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allm.add(path2mod(os.path.join(r,f)))
print('total modules under AlgebraicJacobian/:',len(allm))
imp=re.compile(r'^import\s+(AlgebraicJacobian\S*)')
def imports(path):
    out=[]
    try:
        for line in open(path,encoding='utf-8',errors='replace'):
            m=imp.match(line)
            if m: out.append(m.group(1))
    except FileNotFoundError: pass
    return out
seen=set(); stack=imports('AlgebraicJacobian.lean')
print('direct root imports:',len(stack))
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    stack.extend(imports(mod2path(m)))
print('reachable from root:',len(seen&allm))
un=sorted(allm-seen)
print('UNREACHABLE:',len(un))
for u in un: print('  ',u)
"
